/// Registered customer accounts with email and password authentication.
///
/// This table stores the core identity information for customers who
/// purchase products on the platform. Each customer has exactly one account
/// identified by their email address. The password is stored as a hash for
/// security.
///
/// When a customer deletes their account:
/// - Their profile information in {@link ecommerce_mall_customer_profiles}
/// is deleted
/// - Their orders and order history are preserved (for seller records and
/// legal purposes)
/// - Their reviews are preserved but displayed as "deleted user"
///
/// Customers authenticate using email and password. Session management is
/// handled in the separate {@link ecommerce_mall_customer_sessions} table,
/// and password reset tokens are stored in {@link
/// ecommerce_mall_customer_password_resets}.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ecommerce_mall_customers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Customer's email address used for login and communications. Must be
  /// unique across all customers.
  email String

  /// Hashed password for authentication. The actual password is never stored
  /// in plain text.
  password_hash String

  /// Timestamp when the customer account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the customer account was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the customer account was soft deleted. Null if account is
  /// active. Used for account deletion preservation of orders and reviews.
  deleted_at DateTime? @db.Timestamptz

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  sessions ecommerce_mall_customer_sessions[]
  passwordResets ecommerce_mall_customer_password_resets[]
  wishlistItems ecommerce_mall_wishlist_items[]
  cartItems ecommerce_mall_cart_items[]
  orders ecommerce_mall_orders[]
  shipmentDeliveries ecommerce_mall_shipment_deliveries[]
  cancellationRequests ecommerce_mall_cancellation_requests[]
  refundRequests ecommerce_mall_refund_requests[]
  reviews ecommerce_mall_reviews[]
  adminPromotionRequestCustomers ecommerce_mall_admin_promotion_request_customers[]

  //----
  // INDEXES
  //----
  @@unique([email])
  @@index([created_at])
  @@index([deleted_at])
}

