/**
 * Test the successful approval of an administrator promotion request submitted by a customer.
 *
 * This scenario validates that when a super administrator approves a pending promotion request:
 * (1) The request status changes from 'pending' to 'approved',
 * (2) An administrator record is created for the requesting customer,
 * (3) The reviewer_id is set to the approving super administrator,
 * (4) A snapshot is created to preserve the state transition for audit purposes.
 */
export async function test_api_admin_promotion_request_approve_customer(
  connection: api.IConnection,
) {
  // 1. Create customer connection and register
  const customerConnection: api.IConnection = { host: connection.host };
  const customer = await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
    } satisfies IEcommerceMallCustomer.IJoin,
  });
  typia.assert(customer);
  // 2. Customer creates admin promotion request
  const promotionRequest =
    await generate_random_ecommerce_mall_customer_admin_promotion_requests_create(
      customerConnection,
      {
        body: {
          reason: RandomGenerator.paragraph({ sentences: 3 }),
        } satisfies IEcommerceMallAdminPromotionRequest.ICreate,
      },
    );
  typia.assert(promotionRequest);
  // Verify initial state
  TestValidator.equals(
    "initial status is pending",
    promotionRequest.status,
    "pending",
  );
  TestValidator.equals(
    "reviewer is null initially",
    promotionRequest.reviewer,
    null,
  );
  TestValidator.equals(
    "rejectionReason is null initially",
    promotionRequest.rejectionReason,
    null,
  );
  // 3. Super Admin authentication
  const superAdminConnection: api.IConnection = { host: connection.host };
  const superAdmin = await authorize_super_admin_login(superAdminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
    } satisfies IEcommerceMallSuperAdmin.ILogin,
  });
  typia.assert(superAdmin);
  // 4. Super Admin approves the promotion request
  const approvedRequest =
    await api.functional.ecommerceMall.superAdmin.admin_promotion_requests.update(
      superAdminConnection,
      {
        promotionRequestId: promotionRequest.id,
        body: {
          status: "approved",
          rejectionReason: null,
        } satisfies IEcommerceMallAdminPromotionRequest.IUpdate,
      },
    );
  typia.assert(approvedRequest);
  // 5. Validate approval result
  TestValidator.equals(
    "status changed to approved",
    approvedRequest.status,
    "approved",
  );
  TestValidator.equals(
    "promotion request ID preserved",
    approvedRequest.id,
    promotionRequest.id,
  );
  TestValidator.equals(
    "rejectionReason is null after approval",
    approvedRequest.rejectionReason,
    null,
  );
  // Verify reviewer is set to the super admin
  TestValidator.predicate("reviewer is set", approvedRequest.reviewer !== null);
  if (approvedRequest.reviewer !== null) {
    TestValidator.equals(
      "reviewer ID matches super admin",
      approvedRequest.reviewer.id,
      superAdmin.id,
    );
  }
  // Verify requester information is preserved
  TestValidator.equals(
    "requester ID matches customer",
    approvedRequest.requester.id,
    customer.id,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
