  const paginationRequest: IEcommerceMallSellerRegistration.IRequest = {
    ...baseRequest,
    status: null,
    limit: 2,
    page: 1,
  };
  const page1Result =
    await api.functional.ecommerceMall.seller.seller_registrations.index(
      sellerConnection1,
