  // 5. Test cursor-based pagination
  const cursorPage1 =
    await api.functional.ecommerceMall.seller.seller_registrations.index(
      sellerConnection,
      {
        body: {
          limit: 5,
          cursor: null,
          status: null,
          sellerId: null,
          reviewerId: null,
          createdAtFrom: null,
          createdAtTo: null,
          reviewedAtFrom: null,
          reviewedAtTo: null,
          sortBy: "createdAt",
          sortOrder: "desc",
        } satisfies IEcommerceMallSellerRegistration.IRequest,
      },
    );
  typia.assert(cursorPage1);
  // 6. Test offset-based pagination with page parameter
  const offsetPage1 =
    await api.functional.ecommerceMall.seller.seller_registrations.index(
      sellerConnection,
      {
        body: {
          limit: 5,
          cursor: null,
          status: null,
          sellerId: null,
          reviewerId: null,
          createdAtFrom: null,
          createdAtTo: null,
          reviewedAtFrom: null,
          reviewedAtTo: null,
          sortBy: "createdAt",
          sortOrder: "desc",
          page: 1,
        } satisfies IEcommerceMallSellerRegistration.IRequest,
      },
    );
  typia.assert(offsetPage1);
  const offsetPage2 =
    await api.functional.ecommerceMall.seller.seller_registrations.index(
      sellerConnection,
      {
        body: {
          limit: 5,
          cursor: null,
          status: null,
          sellerId: null,
          reviewerId: null,
          createdAtFrom: null,
          createdAtTo: null,
          reviewedAtFrom: null,
          reviewedAtTo: null,
          sortBy: "createdAt",
          sortOrder: "desc",
          page: 2,
        } satisfies IEcommerceMallSellerRegistration.IRequest,
      },
    );
  typia.assert(offsetPage2);
  // 7. Test empty results - Filter by non-existent sellerId
  const nonExistentSellerId = typia.random<string & tags.Format<"uuid">>();
