      foundRegistration.reviewer,
      null,
    );
    TestValidator.equals(
      "seller id matches",
      foundRegistration.seller.id,
      seller.id,
    );
    TestValidator.equals(
      "seller email matches",
      foundRegistration.seller.email,
      seller.email,
    );
  }
}

