/**
 * Test seller viewing their order items within a specific order.
 *
 * This is the primary success path where a seller retrieves all order items
 * for products they own in an order. Prerequisites include creating a category
 * as admin, creating a product with variant as seller, and completing checkout
 * as customer to create an order.
 */
export async function test_api_seller_order_item_retrieval_success(
  connection: api.IConnection,
): Promise<void> {
  // 1. Authenticate as admin and create category
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  const category = await generate_random_ecommerce_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // 2. Authenticate as seller and create product
  const sellerPassword = RandomGenerator.alphaNumeric(16);
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerResult = await authorize_seller_join(sellerConnection, {
    body: { password: sellerPassword },
  });
  const seller = sellerResult;
  const product = await generate_random_ecommerce_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        categoryId: category.id,
        basePrice: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<1000>
        >(),
      } satisfies IEcommerceMallProduct.ICreate,
    },
  );
  typia.assert(product);
  // 3. Create product variant
  const variant =
    await generate_random_ecommerce_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: {
          skuCode: RandomGenerator.alphaNumeric(10).toUpperCase(),
          options: [
            { optionName: "color", optionValue: "red" },
            { optionName: "size", optionValue: "M" },
          ],
          price: 25000,
          stock: 100,
        } satisfies IEcommerceMallProductVariant.ICreate,
      },
    );
  typia.assert(variant);
  // 4. Authenticate as customer and add variant to cart
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  const cartItem =
    await generate_random_ecommerce_mall_customer_cart_items_create(
      customerConnection,
      {
        body: {
          productVariantId: variant.id,
          quantity: 2,
        } satisfies IEcommerceMallCartItem.ICreate,
      },
    );
  typia.assert(cartItem);
  // 5. Complete checkout to create order
  const order = await generate_random_ecommerce_mall_customer_checkout_create(
    customerConnection,
    {
      body: {
        recipientName: RandomGenerator.name(),
        recipientPhone: RandomGenerator.mobile(),
        streetAddress: RandomGenerator.paragraph({ sentences: 1 }),
        city: RandomGenerator.name(),
        state: RandomGenerator.name(),
        postalCode: RandomGenerator.alphaNumeric(5),
        country: RandomGenerator.name(),
      } satisfies IEcommerceMallOrder.ICreate,
    },
  );
  typia.assert(order);
  // 6. Authenticate as seller (who created the product) and retrieve order items
  const sellerApiConnection: api.IConnection = { host: connection.host };
  await authorize_seller_login(sellerApiConnection, {
    body: {
      email: seller.email,
      password: sellerPassword,
    } satisfies IEcommerceMallSeller.ILogin,
  });
  const orderItemsResult =
    await api.functional.ecommerceMall.seller.orders.items.index(
      sellerApiConnection,
      {
        orderId: order.id,
        body: {
          orderId: order.id,
          page: 1,
          limit: 10,
        } satisfies IEcommerceMallOrderItem.IRequest,
      },
    );
  // 7. Validate response - typia.assert performs complete validation
  typia.assert(orderItemsResult);
  // Validate business logic: seller should see their order items
  TestValidator.predicate(
    "order items data should not be empty",
    orderItemsResult.data.length > 0,
  );
  const firstItem = orderItemsResult.data[0];
  // Validate seller can see their product in the order items
  TestValidator.equals(
    "seller id in order item matches authenticated seller",
    firstItem.seller.id,
    seller.id,
  );
  // Validate product snapshot is present
  TestValidator.equals(
    "product name in snapshot matches created product",
    firstItem.product.name,
    product.name,
  );
  // Validate variant snapshot is present
  TestValidator.equals(
    "variant sku in snapshot matches created variant",
    firstItem.variant.skuCode,
    variant.skuCode,
  );
}

