  TestValidator.equals(
    "snapshot order number matches",
    snapshot.order.orderNumber,
    order.orderNumber,
  );
  TestValidator.equals(
    "snapshot total price matches",
    snapshot.order.totalPrice,
    order.totalPrice,
  );
