/**
 * Test customer can filter order item snapshots by type.
 *
 * This test validates that customers can filter snapshots by snapshotType:
 * 'product', 'variant', 'seller', or null for all types.
 * Snapshots are created automatically during checkout and capture the immutable
 * state of product, variant, and seller at purchase time.
 */
export async function test_api_order_item_snapshots_filter_by_type(
  connection: api.IConnection,
): Promise<void> {
  // 1. Authenticate as admin, seller, and customer
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // 2. Create category as admin (required for product creation)
  const category = await generate_random_ecommerce_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // 3. Create product as seller
  const product = await generate_random_ecommerce_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        categoryId: category.id,
      },
    },
  );
  typia.assert(product);
  // 4. Create product variant as seller
  const variant =
    await generate_random_ecommerce_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: {
          productId: product.id,
        },
      },
    );
  typia.assert(variant);
  // 5. Add variant to customer cart
  const cartItem =
    await generate_random_ecommerce_mall_customer_cart_items_create(
      customerConnection,
      {
        body: {
          productVariantId: variant.id,
          quantity: 1,
        },
      },
    );
  typia.assert(cartItem);
  // 6. Checkout to create order with snapshots
  const order = await generate_random_ecommerce_mall_customer_checkout_create(
    customerConnection,
    {},
  );
  typia.assert(order);
  typia.assert(order.orderItems.length > 0);
  const orderId = order.id;
  const firstItem = typia.assert<IEntity>(order.orderItems[0]);
  const itemId = firstItem.id;
  // 7. Filter by snapshotType: 'product'
  const productSnapshots =
    await api.functional.ecommerceMall.customer.orders.items.snapshots.index(
      customerConnection,
      {
        orderId,
        itemId,
        body: {
          snapshotType: "product",
        } satisfies IEcommerceMallOrderItemSnapshot.IRequest,
      },
    );
  typia.assert(productSnapshots);
  // All returned snapshots should have productSnapshot defined
  for (const snapshot of productSnapshots.data) {
    TestValidator.predicate(
      "productSnapshot exists",
      !!snapshot.productSnapshot,
    );
  }
  // 8. Filter by snapshotType: 'variant'
  const variantSnapshots =
    await api.functional.ecommerceMall.customer.orders.items.snapshots.index(
      customerConnection,
      {
        orderId,
        itemId,
        body: {
          snapshotType: "variant",
        } satisfies IEcommerceMallOrderItemSnapshot.IRequest,
      },
    );
  typia.assert(variantSnapshots);
  // All returned snapshots should have variantSnapshot defined
  for (const snapshot of variantSnapshots.data) {
    TestValidator.predicate(
      "variantSnapshot exists",
      !!snapshot.variantSnapshot,
    );
  }
  // 9. Filter by snapshotType: 'seller'
  const sellerSnapshots =
    await api.functional.ecommerceMall.customer.orders.items.snapshots.index(
      customerConnection,
      {
        orderId,
        itemId,
        body: {
          snapshotType: "seller",
        } satisfies IEcommerceMallOrderItemSnapshot.IRequest,
      },
    );
  typia.assert(sellerSnapshots);
  // All returned snapshots should have sellerSnapshot defined
  for (const snapshot of sellerSnapshots.data) {
    TestValidator.predicate("sellerSnapshot exists", !!snapshot.sellerSnapshot);
  }
  // 10. Retrieve all snapshots without filter (snapshotType: null)
  const allSnapshots =
    await api.functional.ecommerceMall.customer.orders.items.snapshots.index(
      customerConnection,
      {
        orderId,
        itemId,
        body: {
          snapshotType: null,
        } satisfies IEcommerceMallOrderItemSnapshot.IRequest,
      },
    );
  typia.assert(allSnapshots);
  // All three types should be represented
  const hasProduct = allSnapshots.data.some((s) => s.productSnapshot);
  const hasVariant = allSnapshots.data.some((s) => s.variantSnapshot);
  const hasSeller = allSnapshots.data.some((s) => s.sellerSnapshot);
  TestValidator.predicate("all snapshots include product type", hasProduct);
  TestValidator.predicate("all snapshots include variant type", hasVariant);
  TestValidator.predicate("all snapshots include seller type", hasSeller);
}

