export async function test_api_customer_shipments_list_paginated_with_delivery_status(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Admin setup - create category
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, { body: {} });
  const category = await generate_random_ecommerce_mall_admin_categories_create(
    adminConnection,
    { body: {} },
  );
  typia.assert(category);
  // Step 2: Seller setup - join, register, and create product
  const sellerConnection: api.IConnection = { host: connection.host };
  const seller = await authorize_seller_join(sellerConnection, { body: {} });
  await generate_random_ecommerce_mall_seller_registrations_create(
    sellerConnection,
    {
      body: {
        taxIdentificationNumber: typia.random<string>(),
        businessRegistrationNumber: typia.random<string>(),
        businessName: RandomGenerator.name(),
        businessAddress: RandomGenerator.paragraph({ sentences: 2 }),
      },
    },
  );
  const product = await generate_random_ecommerce_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.name(),
        description: RandomGenerator.paragraph({ sentences: 5 }),
        categoryId: category.id,
        basePrice: typia.random<number & tags.Minimum<1000>>(),
      },
    },
  );
  typia.assert(product);
  // Step 3: Create variant with initial stock
  const variant =
    await generate_random_ecommerce_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: {
          skuCode: RandomGenerator.alphaNumeric(8).toUpperCase(),
          options: [
            { optionName: "Size", optionValue: "Large" },
            { optionName: "Color", optionValue: "Red" },
          ],
          price: product.basePrice,
          stock: 100,
        },
      },
    );
  typia.assert(variant);
  // Step 4: Add inventory to variant
  await generate_random_ecommerce_mall_seller_variants_inventory_create(
    sellerConnection,
    {
      params: { variantId: variant.id },
      body: {
        quantity: 50,
        reason: "Initial restocking",
      },
    },
  );
  // Step 5: Customer setup - join and add to cart
  const customerConnection: api.IConnection = { host: connection.host };
  const customer = await authorize_customer_join(customerConnection, {
    body: {},
  });
  const cartItem = await generate_random_ecommerce_mall_customer_cart_create(
    customerConnection,
    {
      body: {
        productVariantId: variant.id,
        quantity: 2,
      },
    },
  );
  typia.assert(cartItem);
  // Step 6: Checkout to create order
  const order = await generate_random_ecommerce_mall_customer_checkout_create(
    customerConnection,
    {
      body: {
        recipientName: RandomGenerator.name(),
        recipientPhone: RandomGenerator.mobile(),
        streetAddress: "123 Test Street",
        city: "Test City",
        state: "Test State",
        postalCode: "12345",
        country: "Test Country",
      },
    },
  );
  typia.assert(order);
  // Step 7: Seller creates shipment with tracking
  const orderItemSummaries =
    order.orderItems as IEcommerceMallOrderItem.ISummary[];
  const shipment = await generate_random_ecommerce_mall_seller_shipments_create(
    sellerConnection,
    {
      body: {
        orderItemIds: orderItemSummaries.map((item) => item.id),
        carrierName: "FedEx",
        trackingNumber: RandomGenerator.alphaNumeric(12).toUpperCase(),
      },
    },
  );
  typia.assert(shipment);
  // Step 8: Customer lists shipments with pagination
  const shipmentsPage =
    await api.functional.ecommerceMall.customer.shipments.index(
      customerConnection,
      {
        body: {
          orderId: order.id,
          page: 1,
          limit: 10,
          sort: ["-shippedAt"],
        } satisfies IEcommerceMallShipment.IRequest,
      },
    );
  typia.assert(shipmentsPage);
  // Step 9: Validate pagination fields
  TestValidator.equals(
    "pagination current page",
    shipmentsPage.pagination.current,
    1,
  );
  TestValidator.equals("pagination limit", shipmentsPage.pagination.limit, 10);
  TestValidator.equals(
    "pagination records count",
    shipmentsPage.pagination.records,
    1,
  );
  TestValidator.equals(
    "pagination pages count",
    shipmentsPage.pagination.pages,
    1,
  );
  // Step 10: Validate shipment belongs to customer's order
  TestValidator.equals("data array length", shipmentsPage.data.length, 1);
  const customerShipment = shipmentsPage.data[0];
  TestValidator.equals(
    "shipment belongs to correct order",
    customerShipment.orderId,
    order.id,
  );
  // Step 11: Validate carrier and tracking information
  TestValidator.equals("carrier name", customerShipment.carrierName, "FedEx");
  TestValidator.predicate(
    "tracking number exists",
    customerShipment.trackingNumber.length > 0,
  );
  // Step 12: Validate delivery status (null for undelivered)
  TestValidator.equals(
    "delivery status is null (undelivered)",
    customerShipment.delivery,
    null,
  );
  // Step 13: Validate seller info is correct
  TestValidator.equals(
    "seller ID matches",
    customerShipment.seller.id,
    seller.id,
  );
  // Step 14: Validate shipment timestamps exist
  TestValidator.predicate(
    "shippedAt timestamp exists",
    typeof customerShipment.shippedAt === "string",
  );
  TestValidator.predicate(
    "createdAt timestamp exists",
    typeof customerShipment.createdAt === "string",
  );
  TestValidator.predicate(
    "updatedAt timestamp exists",
    typeof customerShipment.updatedAt === "string",
  );
}

