export async function test_api_shipment_invalid_status_items_rejected(
  connection: api.IConnection,
): Promise<void> {
  // Setup admin and create category
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  const category = await generate_random_ecommerce_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // Setup seller and create product with variant
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  const product = await generate_random_ecommerce_mall_seller_products_create(
    sellerConnection,
    {
      body: { categoryId: category.id },
    },
  );
  typia.assert(product);
  const variant =
    await generate_random_ecommerce_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: { stock: 100 },
      },
    );
  typia.assert(variant);
  // Setup customer, add to cart, and checkout to create paid order
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  await generate_random_ecommerce_mall_customer_cart_items_create(
    customerConnection,
    {
      body: { productVariantId: variant.id, quantity: 1 },
    },
  );
  const order = await generate_random_ecommerce_mall_customer_checkout_create(
    customerConnection,
    {
      body: {
        recipientName: "Test Recipient",
        recipientPhone: "01012345678",
        streetAddress: "123 Test Street",
        city: "Test City",
        state: null,
        postalCode: "12345",
        country: "Test Country",
      } satisfies IEcommerceMallOrder.ICreate,
    },
  );
  typia.assert(order);
  // Extract order item IDs from the created order
  const orderItemIds = (
    order.orderItems as IEcommerceMallOrderItem.ISummary[]
  ).map((item) => item.id);
  // Create first shipment - should succeed and change item status to 'shipped'
  const firstShipment =
    await generate_random_ecommerce_mall_seller_shipments_create(
      sellerConnection,
      {
        body: {
          orderItemIds: orderItemIds as (string & tags.Format<"uuid">)[],
          carrierName: "FedEx",
          trackingNumber: "TRACK123456",
        } satisfies IEcommerceMallShipment.ICreate,
      },
    );
  typia.assert(firstShipment);
  // Attempt to create second shipment with same items - should fail because items are now 'shipped', not 'paid'
  await TestValidator.error(
    "shipment creation fails for already shipped items",
    async () => {
      await api.functional.ecommerceMall.seller.shipments.create(
        sellerConnection,
        {
          body: {
            orderItemIds: orderItemIds as (string & tags.Format<"uuid">)[],
            carrierName: "UPS",
            trackingNumber: "TRACK789012",
          } satisfies IEcommerceMallShipment.ICreate,
        },
      );
    },
  );
}

