/**
 * Test customer ownership boundary enforcement for shipment delivery confirmation.
 * Verifies that only the customer who owns the order can confirm delivery of its shipments.
 * When a different authenticated customer attempts to confirm delivery, the system must
 * reject the operation with an authorization error. This validates data isolation boundaries
 * where customers cannot access or modify shipments belonging to other customers' orders.
 */
export async function test_api_shipment_delivery_customer_ownership_boundary_enforcement(
  connection: api.IConnection,
): Promise<void> {
  // 1. Setup: Admin creates category for product
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
    },
  });
  const category = await generate_random_ecommerce_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // 2. Setup: Seller creates product and variant
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerCredentials = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
  };
  await authorize_seller_join(sellerConnection, {
    body: sellerCredentials,
  });
  const product = await generate_random_ecommerce_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        categoryId: category.id,
        name: RandomGenerator.name(),
        description: RandomGenerator.paragraph({ sentences: 3 }),
        basePrice: randint(100, 1000),
      },
    },
  );
  typia.assert(product);
  const variant =
    await generate_random_ecommerce_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: {
          skuCode: RandomGenerator.alphaNumeric(10),
          options: [{ optionName: "Color", optionValue: "Red" }],
          stock: 10,
        },
      },
    );
  typia.assert(variant);
  // 3. Customer A: Create account, add to cart, and checkout to create order
  const customerAConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerAConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
    },
  });
  await generate_random_ecommerce_mall_customer_cart_items_create(
    customerAConnection,
    {
      body: {
        productVariantId: variant.id,
        quantity: 1,
      },
    },
  );
  const order = await generate_random_ecommerce_mall_customer_checkout_create(
    customerAConnection,
    {
      body: {
        recipientName: RandomGenerator.name(),
        recipientPhone: RandomGenerator.mobile(),
        streetAddress: RandomGenerator.paragraph({ sentences: 1 }),
        city: RandomGenerator.name(),
        state: RandomGenerator.name(),
        postalCode: RandomGenerator.alphaNumeric(5),
        country: RandomGenerator.name(),
      },
    },
  );
  typia.assert(order);
  // Extract order item ID for shipment creation
  const orderItem = typia.assert<IEcommerceMallOrderItem & IEntity>(order.orderItems[0]);
  // 4. Seller creates shipment for Customer A's order item
  const shipment = await generate_random_ecommerce_mall_seller_shipments_create(
    sellerConnection,
    {
      body: {
        orderItemIds: [orderItem.id],
        carrierName: "FedEx",
        trackingNumber: RandomGenerator.alphaNumeric(12),
      },
    },
  );
  typia.assert(shipment);
  // 5. Customer B: Create different customer account
  const customerBConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerBConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
    },
  });
  // 6. Test: Customer B attempts to confirm delivery of Customer A's shipment
  // This should fail with authorization error since Customer B doesn't own the order
  await TestValidator.error(
    "unauthorized customer cannot confirm another customer's shipment delivery",
    async () => {
      await api.functional.ecommerceMall.customer.shipments.deliveries.confirmDelivery(
        customerBConnection,
        { shipmentId: shipment.id },
      );
    },
  );
}

