/**
 * Test customer refund request access boundary enforcement.
 *
 * Scenario: Verify that customers can only view their own refund requests.
 * When customer2 attempts to retrieve a refund request belonging to customer1,
 * the system must reject the access with a 403 Forbidden error.
 *
 * Sequence:
 * 1. Admin joins and creates category
 * 2. Seller joins, creates product and variant
 * 3. Customer1 joins, adds item to cart, and checks out (creates order)
 * 4. Seller creates shipment for the order
 * 5. Customer1 confirms delivery
 * 6. Customer1 creates refund request
 * 7. Customer2 joins
 * 8. Customer2 attempts to retrieve customer1's refund request
 * 9. Verify access is denied with appropriate error
 */
export async function test_api_customer_refund_request_access_boundary_enforcement(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin setup - create admin and category
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "AdminPass123!",
      href: "http://localhost:3000",
      referrer: "http://localhost:3000",
      ip: "127.0.0.1",
    },
  });
  const category = await generate_random_ecommerce_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // 2. Seller setup - create seller, product, and variant
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "SellerPass123!",
      href: "http://localhost:3000",
      referrer: "http://localhost:3000",
      ip: "127.0.0.1",
    },
  });
  const product = await generate_random_ecommerce_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        categoryId: category.id,
      },
    },
  );
  typia.assert(product);
  const variant =
    await generate_random_ecommerce_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: {
          stock: 10,
        },
      },
    );
  typia.assert(variant);
  // 3. Customer1 setup - create customer and add to cart
  const customer1Connection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customer1Connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Customer1Pass!",
    },
  });
  const cartItem =
    await generate_random_ecommerce_mall_customer_cart_items_create(
      customer1Connection,
      {
        body: {
          productVariantId: variant.id,
          quantity: 1,
        },
      },
    );
  typia.assert(cartItem);
  // 4. Checkout - create order
  const order = await generate_random_ecommerce_mall_customer_checkout_create(
    customer1Connection,
    {
      body: {
        recipientName: "Test Recipient",
        recipientPhone: "01012345678",
        streetAddress: "123 Test Street",
        city: "Seoul",
        state: null,
        postalCode: "12345",
        country: "South Korea",
      },
    },
  );
  typia.assert(order);
  const orderItem = typia.assert<IEcommerceMallOrderItem & IEntity>(order.orderItems[0]);
  // 5. Seller creates shipment
  const shipment = await generate_random_ecommerce_mall_seller_shipments_create(
    sellerConnection,
    {
      body: {
        orderItemIds: [orderItem.id],
        carrierName: "Test Carrier",
        trackingNumber: "TRACK123456",
      },
    },
  );
  typia.assert(shipment);
  // 6. Customer1 confirms delivery
  const delivery =
    await api.functional.ecommerceMall.customer.shipments.delivery.confirm.confirmDelivery(
      customer1Connection,
      {
        shipmentId: shipment.id,
      },
    );
  typia.assert(delivery);
  // 7. Customer1 creates refund request
  const refundRequest =
    await generate_random_ecommerce_mall_customer_refund_requests_create(
      customer1Connection,
      {
        body: {
          orderItemId: orderItem.id,
          reason: "Product is defective and not as described",
        },
      },
    );
  typia.assert(refundRequest);
  // 8. Customer2 setup
  const customer2Connection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customer2Connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Customer2Pass!",
    },
  });
  // 9. Customer2 tries to access customer1's refund request - should get 403
  await TestValidator.httpError(
    "customer2 cannot access customer1's refund request - 403 Forbidden",
    403,
    async () => {
      await api.functional.ecommerceMall.customer.refundRequests.at(
        customer2Connection,
        {
          refundRequestId: refundRequest.id,
        },
      );
    },
  );
}

