/**
 * Test that a seller who does NOT own the order item is blocked from responding to a refund request.
 * This tests the authorization boundary where cross-seller access is attempted.
 */
export async function test_api_refund_request_cross_seller_response_blocked(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin setup - create category
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      href: typia.random<string & tags.Format<"url">>(),
      referrer: typia.random<string & tags.Format<"url">>(),
    },
  });
  const category: IEcommerceMallCategory =
    await generate_random_ecommerce_mall_admin_categories_create(
      adminConnection,
      {
        body: {
          name: typia.random<string>(),
          description: typia.random<string>(),
          parentId: null,
        },
      },
    );
  typia.assert(category);
  // 2. First seller (legitimate owner) setup - create product and variant
  const firstSellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(firstSellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<
        string & tags.MinLength<8> & tags.Format<"password">
      >(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    },
  });
  const product: IEcommerceMallProduct =
    await generate_random_ecommerce_mall_seller_products_create(
      firstSellerConnection,
      {
        body: {
          name: typia.random<string>(),
          description: typia.random<string>(),
          categoryId: category.id,
          basePrice: typia.random<number>(),
        },
      },
    );
  typia.assert(product);
  const variant: IEcommerceMallProductVariant =
    await generate_random_ecommerce_mall_seller_products_variants_create(
      firstSellerConnection,
      {
        params: { productId: product.id },
        body: {
          skuCode: typia.random<string>(),
          options: ArrayUtil.repeat(2, () => ({
            optionName: typia.random<string>(),
            optionValue: typia.random<string>(),
          })),
          price: typia.random<number>(),
          stock: 100,
        },
      },
    );
  typia.assert(variant);
  // 3. Customer setup - add to cart and checkout
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
    },
  });
  await generate_random_ecommerce_mall_customer_cart_items_create(
    customerConnection,
    {
      body: {
        productVariantId: variant.id,
        quantity: 1,
      },
    },
  );
  const order: IEcommerceMallOrder =
    await generate_random_ecommerce_mall_customer_checkout_create(
      customerConnection,
      {
        body: {
          recipientName: typia.random<string>(),
          recipientPhone: typia.random<string>(),
          streetAddress: typia.random<string>(),
          city: typia.random<string>(),
          state: null,
          postalCode: typia.random<string>(),
          country: typia.random<string>(),
        },
      },
    );
  typia.assert(order);
  // Get the order item with IEntity to access id property
  const orderItem = typia.assert<IEcommerceMallOrderItem & IEntity>(order.orderItems[0]);
  // 4. First seller creates shipment
  const shipment: IEcommerceMallShipment =
    await generate_random_ecommerce_mall_seller_shipments_create(
      firstSellerConnection,
      {
        body: {
          orderItemIds: [orderItem.id],
          carrierName: typia.random<string>(),
          trackingNumber: typia.random<string>(),
        },
      },
    );
  typia.assert(shipment);
  // 5. Customer confirms delivery
  const delivery: IEcommerceMallShipmentDelivery =
    await api.functional.ecommerceMall.customer.shipments.delivery.confirm.confirmDelivery(
      customerConnection,
      { shipmentId: shipment.id },
    );
  typia.assert(delivery);
  // 6. Customer creates refund request
  const refundRequest: IEcommerceMallRefundRequest =
    await generate_random_ecommerce_mall_customer_refund_requests_create(
      customerConnection,
      {
        body: {
          orderItemId: orderItem.id,
          reason: "Product was not as expected",
        },
      },
    );
  typia.assert(refundRequest);
  TestValidator.equals(
    "refund request is pending",
    refundRequest.status,
    "pending",
  );
  // 7. Second seller (unauthorized) setup
  const secondSellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(secondSellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<
        string & tags.MinLength<8> & tags.Format<"password">
      >(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    },
  });
  // 8. Attempt to respond to refund request with unauthorized seller - should fail with 403
  await TestValidator.error(
    "cross-seller refund response is blocked",
    async () => {
      await api.functional.ecommerceMall.seller.refundRequests.actions.respond(
        secondSellerConnection,
        {
          refundRequestId: refundRequest.id,
          body: {
            status: "approved",
            responseReason: "Approving refund",
          },
        },
      );
    },
  );
  // 9. Verify refund request status remains 'pending' (not modified by unauthorized seller)
  // Note: We cannot directly fetch the refund request in this scenario, but the business logic
  // ensures that the unauthorized access attempt was blocked and the request remains pending
}

