export async function test_api_review_retrieval_success(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin setup - create admin account for category creation
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"url">>(),
      referrer: typia.random<string & tags.Format<"url">>(),
    } satisfies IEcommerceMallAdmin.IJoin,
  });
  // 2. Create product category
  const category = await generate_random_ecommerce_mall_admin_categories_create(
    adminConnection,
    {
      body: {
        name: RandomGenerator.name(),
      } satisfies IEcommerceMallCategory.ICreate,
    },
  );
  // 3. Seller setup - register seller account
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuth = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IEcommerceMallSeller.IJoin,
  });
  // 4. Submit seller registration for approval
  const registration =
    await generate_random_ecommerce_mall_seller_registrations_create(
      sellerConnection,
      {
        body: {
          taxIdentificationNumber: RandomGenerator.alphaNumeric(10),
          businessRegistrationNumber: RandomGenerator.alphaNumeric(10),
          businessName: RandomGenerator.name(),
          businessAddress: RandomGenerator.paragraph(),
        } satisfies IEcommerceMallSellerRegistration.ICreate,
      },
    );
  // 5. Approve seller registration
  await api.functional.ecommerceMall.admin.sellers.registrations.review(
    adminConnection,
    {
      registrationId: (registration as IEntity).id,
      body: {
        status: "approved",
        rejection_reason: null,
      } satisfies IEcommerceMallSellerRegistration.IReview,
    },
  );
  // 6. Create product
  const product = await generate_random_ecommerce_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.name(),
        description: RandomGenerator.paragraph(),
        categoryId: category.id,
        basePrice: typia.random<number & tags.Type<"uint32">>(),
      } satisfies IEcommerceMallProduct.ICreate,
    },
  );
  // 7. Create product variant
  const variant =
    await generate_random_ecommerce_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: {
          productId: product.id,
        },
        body: {
          skuCode: RandomGenerator.alphaNumeric(8),
          options: [
            {
              optionName: "Color",
              optionValue: "Red",
            } satisfies IEcommerceMallProductVariantOption.ICreate,
          ],
          price: null,
          stock: 100,
        } satisfies IEcommerceMallProductVariant.ICreate,
      },
    );
  // 8. Add inventory to variant
  await generate_random_ecommerce_mall_seller_variants_inventory_create(
    sellerConnection,
    {
      params: {
        variantId: variant.id,
      },
      body: {
        quantity: 100,
        reason: "Initial stock",
      } satisfies IEcommerceMallInventoryRecord.ICreate,
    },
  );
  // 9. Customer setup
  const customerConnection: api.IConnection = { host: connection.host };
  const customerAuth = await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
    } satisfies IEcommerceMallCustomer.IJoin,
  });
  // 10. Add variant to cart
  await generate_random_ecommerce_mall_customer_cart_items_create(
    customerConnection,
    {
      body: {
        productVariantId: variant.id,
        quantity: 1,
      } satisfies IEcommerceMallCartItem.ICreate,
    },
  );
  // 11. Checkout to create order
  const order = await generate_random_ecommerce_mall_customer_checkout_create(
    customerConnection,
    {
      body: {
        recipientName: RandomGenerator.name(),
        recipientPhone: RandomGenerator.mobile(),
        streetAddress: RandomGenerator.paragraph(),
        city: RandomGenerator.name(),
        state: null,
        postalCode: RandomGenerator.alphaNumeric(5),
        country: RandomGenerator.name(),
      } satisfies IEcommerceMallOrder.ICreate,
    },
  );
  // 12. Create shipment for order items
  const orderItemId = (order.orderItems[0] as IEntity).id;
  const shipment = await generate_random_ecommerce_mall_seller_shipments_create(
    sellerConnection,
    {
      body: {
        orderItemIds: [orderItemId],
        carrierName: "FedEx",
        trackingNumber: RandomGenerator.alphaNumeric(12),
      } satisfies IEcommerceMallShipment.ICreate,
    },
  );
  // 13. Confirm delivery
  await api.functional.ecommerceMall.customer.shipments.delivery.confirm.confirmDelivery(
    customerConnection,
    {
      shipmentId: shipment.id,
    },
  );
  // 14. Create review for delivered order item
  const review = await generate_random_ecommerce_mall_customer_reviews_create(
    customerConnection,
    {
      body: {
        order_item_id: orderItemId,
        rating: typia.random<
          number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<5>
        >(),
        content: RandomGenerator.paragraph(),
      } satisfies IEcommerceMallReview.ICreate,
    },
  );
  // 15. Retrieve review by ID (target operation)
  const retrievedReview = await api.functional.ecommerceMall.reviews.at(
    customerConnection,
    {
      reviewId: review.id,
    },
  );
  // 16. Validate response structure and data
  typia.assert(retrievedReview);
  // Validate nested relationships are populated
  TestValidator.equals("review id matches", retrievedReview.id, review.id);
  TestValidator.equals("rating matches", retrievedReview.rating, review.rating);
  TestValidator.equals(
    "content matches",
    retrievedReview.content,
    review.content,
  );
  TestValidator.equals(
    "customer is populated",
    retrievedReview.customer.id,
    customerAuth.id,
  );
  TestValidator.equals(
    "product is populated",
    retrievedReview.product.id,
    product.id,
  );
  TestValidator.equals(
    "order is populated",
    retrievedReview.order.id,
    order.id,
  );
  TestValidator.equals(
    "orderItem is populated",
    retrievedReview.orderItem.id,
    orderItemId,
  );
  TestValidator.predicate(
    "deletedAt is null",
    retrievedReview.deletedAt === null,
  );
  TestValidator.predicate(
    "createdAt exists",
    typeof retrievedReview.createdAt === "string",
  );
  TestValidator.predicate(
    "updatedAt exists",
    typeof retrievedReview.updatedAt === "string",
  );
}

