    superAdmin.id,
  );
  TestValidator.predicate(
    "reviewed_at timestamp exists",
    () => (approvedRegistration as any).reviewed_at !== null,
  );
  TestValidator.equals(
    "rejection_reason is null",
    (approvedRegistration as any).rejection_reason,
    null,
  );
}

