export async function test_api_admin_promotion_request_approve_success(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create super admin account
  const superAdminConnection: api.IConnection = { host: connection.host };
  const superAdmin = await api.functional.ecommerceMall.auth.superAdmin.join(
    superAdminConnection,
    {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: RandomGenerator.alphaNumeric(16),
        href: "https://test.com/superadmin/join",
        referrer: "https://test.com/",
      } satisfies IEcommerceMallSuperAdmin.IJoin,
    },
  );
  typia.assert(superAdmin);
  // 2. Create customer account
  const customerConnection: api.IConnection = { host: connection.host };
  const customer = await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
    },
  });
  typia.assert(customer);
  // 3. Customer submits promotion request
  const promotionRequest =
    await generate_random_ecommerce_mall_customer_admin_promotion_requests_create(
      customerConnection,
      {
        body: {
          reason: RandomGenerator.paragraph({ sentences: 3 }),
        },
      },
    );
  typia.assert(promotionRequest);
  // Verify initial state is pending
  TestValidator.equals(
    "initial status is pending",
    promotionRequest.status,
    "pending",
  );
  TestValidator.equals(
    "initial reviewer is null",
    promotionRequest.reviewer,
    null,
  );
  // 4. Super admin approves the promotion request
  const approvedRequest =
    await api.functional.ecommerceMall.superAdmin.admins.promotion_requests.review(
      superAdminConnection,
      {
        promotionRequestId: promotionRequest.id,
        body: {
          decision: "approve",
          rejectionReason: null,
        } satisfies IEcommerceMallAdminPromotionRequest.IReview,
      },
    );
  typia.assert(approvedRequest);
  // 5. Validate approval response
  TestValidator.equals(
    "status changed to approved",
    approvedRequest.status,
    "approved",
  );
  TestValidator.equals(
    "reviewer is populated",
    approvedRequest.reviewer?.id,
    superAdmin.id,
  );
  TestValidator.equals(
    "reviewer email matches",
    approvedRequest.reviewer?.email,
    superAdmin.email,
  );
  TestValidator.equals(
    "requester matches customer",
    approvedRequest.requester.id,
    customer.id,
  );
  TestValidator.equals(
    "rejection reason is null",
    approvedRequest.rejectionReason,
    null,
  );
  TestValidator.predicate(
    "createdAt is preserved",
    approvedRequest.createdAt === promotionRequest.createdAt,
  );
  TestValidator.predicate(
    "id is preserved",
    approvedRequest.id === promotionRequest.id,
  );
}

