    "super_admin",
  );
  TestValidator.equals(
    "second super admin grade",
    superAdmin2.grade,
    "super_admin",
  );
  // Demote the second super administrator to regular using the first super administrator
  const demotedAdmin =
    await api.functional.ecommerceMall.superAdmin.admins.grade.updateGrade(
