            email: true,
            created_at: true,
            updated_at: true,
            deleted_at: true,
          },
        } satisfies Prisma.ecommerce_mall_customersFindManyArgs,
        seller: {
          select: {
            id: true,
            email: true,
            approval_status: true,
            created_at: true,
            updated_at: true,
            deleted_at: true,
          },
        } satisfies Prisma.ecommerce_mall_sellersFindManyArgs,
        orderItem: {
          select: {
            id: true,
            quantity: true,
            price_at_purchase: true,
            status: true,
            created_at: true,
            product: {
              select: {
                id: true,
                name: true,
                base_price: true,
                seller: {
                  select: {
                    id: true,
                    email: true,
                    approval_status: true,
                    created_at: true,
                    updated_at: true,
                    deleted_at: true,
                  },
                } satisfies Prisma.ecommerce_mall_sellersFindManyArgs,
                category: {
                  select: {
                    id: true,
                    name: true,
                    description: true,
                    created_at: true,
                    parent: {
                      select: {
                        id: true,
                        name: true,
                      },
                    },
                  },
                } satisfies Prisma.ecommerce_mall_categoriesFindManyArgs,
                images: {
                  select: {
                    id: true,
                    image_url: true,
                    display_order: true,
                  },
                  where: { display_order: 0 },
                  take: 1,
                } satisfies Prisma.ecommerce_mall_product_imagesFindManyArgs,
                variants: {
                  select: {
                    price: true,
                    inventoryRecords: {
                      select: {
                        quantity_change: true,
                      },
                    },
                  },
                } satisfies Prisma.ecommerce_mall_product_variantsFindManyArgs,
                reviews: {
                  select: { rating: true },
