                inventoryRecords: {
                  select: {
                    quantity_change: true,
                  },
                } satisfies Prisma.ecommerce_mall_inventory_recordsFindManyArgs,
              },
            } satisfies Prisma.ecommerce_mall_product_variantsFindManyArgs,
            seller: {
              select: {
                id: true,
                email: true,
                approval_status: true,
                created_at: true,
