          .status as IEcommerceMallOrderItem.ISummary["status"],
        createdAt: input.orderItem.created_at.toISOString(),
        product: {
          id: input.orderItem.product.id,
          name: input.orderItem.product.name,
          thumbnail:
            input.orderItem.product.images.length > 0
              ? ({
