export async function postEcommerceMallAuthCustomerJoin(props: {
  ip: string;
  body: IEcommerceMallCustomer.IJoin;
}): Promise<IEcommerceMallCustomer.IAuthorized> {
  // Check email uniqueness - accounts that are NOT soft-deleted
  const existing = await MyGlobal.prisma.ecommerce_mall_customers.count({
    where: {
      email: props.body.email,
      deleted_at: null,
    },
  });
  if (existing > 0) {
    throw new HttpException("Email already registered", 409);
  }
  const customerId = v4() as string & tags.Format<"uuid">;
  const sessionId = v4() as string & tags.Format<"uuid">;
  const nowDate = new Date();
  const nowIso = nowDate.toISOString() as string & tags.Format<"date-time">;
  // Hash password
  const passwordHash = await PasswordUtil.hash(props.body.password);
  // Create customer record
  await MyGlobal.prisma.ecommerce_mall_customers.create({
    data: {
      id: customerId,
      email: props.body.email,
      password_hash: passwordHash,
      created_at: nowDate,
      updated_at: nowDate,
      deleted_at: null,
    },
  });
  // Create session
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
  await MyGlobal.prisma.ecommerce_mall_customer_sessions.create({
    data: {
      id: sessionId,
      ecommerce_mall_customer_id: customerId,
      ip: props.ip,
      href: "",
      referrer: "",
      created_at: nowDate,
      expired_at: accessExpires,
    },
  });
  // Generate JWT tokens
  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: "customer",
        id: customerId,
        session_id: sessionId,
        created_at: nowIso,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "1h", issuer: "autobe" },
    ),
    refresh: jwt.sign(
      {
        type: "customer",
        id: customerId,
        session_id: sessionId,
        tokenType: "refresh",
        created_at: nowIso,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "7d", issuer: "autobe" },
    ),
    expired_at: accessExpires.toISOString() as string &
      tags.Format<"date-time">,
    refreshable_until: refreshExpires.toISOString() as string &
      tags.Format<"date-time">,
  };
  // Construct IAuthorized response
  return {
    id: customerId,
    email: props.body.email,
    createdAt: nowIso,
    updatedAt: nowIso,
    deletedAt: null,
    customerId: customerId,
    displayName: null,
    phoneNumber: null,
    profile: {
      id: customerId,
      customerId: customerId,
      displayName: null,
      phoneNumber: null,
      createdAt: nowIso,
      updatedAt: nowIso,
    } satisfies IEcommerceMallCustomer,
    token,
  } satisfies IEcommerceMallCustomer.IAuthorized;
}

