    const variantSummary: IEcommerceMallProductVariant.ISummary = {
      id: item.variant.id,
      skuCode: item.variant.sku_code,
      price: item.variant.price,
      options: variantOptions,
      currentStock: 0,
      isAvailable: true,
      createdAt: toISOStringSafe(item.variant.created_at),
