    MyGlobal.prisma.ecommerce_mall_order_items.findMany({
      where,
      skip,
      take: limit,
      orderBy,
      ...EcommerceMallOrderItemAtSummaryTransformer.select(),
    }),
    MyGlobal.prisma.ecommerce_mall_order_items.count({ where }),
  ]);
