  const snapshots =
    await MyGlobal.prisma.ecommerce_mall_order_item_product_snapshots.findMany({
      where: whereInput,
      skip,
      take: limit,
      orderBy: { created_at: "desc" },
      select: {
        id: true,
        name: true,
        category_name: true,
        base_price: true,
