@Controller("/ecommerceMall/auth/admin")
export class EcommercemallAuthAdminController {
  /**
   * Creates a new administrator account with email and password credentials, assigning regular administrator privileges by default.
   *
   * This endpoint allows platform setup of initial administrators or creation by existing administrators. The email must be unique across all administrator accounts. Upon successful registration, the administrator receives JWT tokens for immediate authentication.
   *
   * The registration process validates email format, enforces password complexity requirements (minimum 8 characters with mixed case, numbers, and symbols), and creates an active account with 'regular' grade. Super administrator privileges require separate promotion workflow via admin promotion requests.
   *
   * Related tables:
   * - ecommerce_mall_admins: Stores credential and identity information
   * - ecommerce_mall_admin_sessions: Records the initial login session with connection metadata
   *
   * Security considerations:
   * - Passwords are hashed using BCrypt before storage
   * - Token expiration is enforced for both access and refresh tokens
   * - Email uniqueness is strictly enforced at database level with @@unique constraint
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Administrator registration credentials with email and password
   * @x-autobe-authorization-type join
   * @x-autobe-authorization-actor admin
   * @x-autobe-specification Implement administrator registration by validating the request body contains both email and password conforming to platform standards. Check email uniqueness against ecommerce_mall_admins.email field using case-insensitive comparison. Hash the password using BCrypt with a work factor of 10-12 and store in password_hash field. Set grade to 'regular' for initial administrator creation (super admin promotion requires separate approval workflow). Set status to 'active' by default. Create initial session record in ecommerce_mall_admin_sessions capturing IP address, href, and referrer from request metadata. Generate JWT access token and refresh token with appropriate expiration times. Return IEcommerceMallAdmin.IAuthorized containing the tokens and administrator profile information including the assigned grade and status.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("join")
  public async join(
    @Ip()
    ip: string,
    @TypedBody()
    body: IEcommerceMallAdmin.IJoin,
  ): Promise<IEcommerceMallAdmin.IAuthorized> {
    try {
      return await postEcommerceMallAuthAdminJoin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Authenticates an administrator using email and password credentials, returning JWT tokens upon successful validation.
   *
   * This endpoint validates administrator credentials against the ecommerce_mall_admins table. The email lookup is case-insensitive. Password verification uses BCrypt comparison with the stored hash.
   *
   * Account status restrictions:
   * - 'active': Login permitted, tokens issued
   * - 'suspended': Login denied, suspended account error returned
   * - 'banned': Login denied, banned account error returned
   *
   * Successful login creates a session audit trail in ecommerce_mall_admin_sessions capturing connection metadata (IP, href, referrer) for security monitoring. Sessions have expiration timestamps for security.
   *
   * Related tables:
   * - ecommerce_mall_admins: Source of credentials and account status
   * - ecommerce_mall_admin_sessions: Audit trail of login sessions
   *
   * Error scenarios:
   * - Invalid email or password: Generic authentication failure
   * - Suspended account: Account suspension notification
   * - Banned account: Account ban notification
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Administrator login credentials with email and password
   * @x-autobe-authorization-type login
   * @x-autobe-authorization-actor admin
   * @x-autobe-specification Implement administrator login by retrieving the administrator record from ecommerce_mall_admins where email matches the request email using case-insensitive comparison. Verify the provided password against the stored password_hash using BCrypt comparison. Check account status field - only allow login for 'active' status; reject with appropriate error for 'suspended' or 'banned' statuses. Upon successful authentication, create a new session record in ecommerce_mall_admin_sessions with the administrator's ID, current IP address, request href, and referrer headers, plus expiration timestamp. Generate new JWT access token and refresh token pair. Update any existing expired session handling as needed. Return IEcommerceMallAdmin.IAuthorized containing tokens and full administrator profile including grade (regular or super_admin) and status.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("login")
  public async login(
    @Ip()
    ip: string,
    @TypedBody()
    body: IEcommerceMallAdmin.ILogin,
  ): Promise<IEcommerceMallAdmin.IAuthorized> {
    try {
      return await postEcommerceMallAuthAdminLogin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Refreshes an expired access token using a valid refresh token, extending the administrator's session without requiring re-login.
   *
   * This endpoint allows administrators to maintain sessions beyond the access token lifetime by presenting a refresh token. The refresh token must correspond to an active, non-expired session in ecommerce_mall_admin_sessions.
   *
   * Account status validation:
   * - Even with a valid refresh token, the administrator account must have 'active' status
   * - Suspended or banned accounts will have their refresh tokens invalidated
   *
   * The refresh process:
   * 1. Validates the refresh token against session records
   * 2. Verifies the session has not expired
   * 3. Confirms the administrator account is still active
   * 4. Generates a new access token with fresh expiration
   * 5. Optionally rotates the refresh token for security
   *
   * Related tables:
   * - ecommerce_mall_admin_sessions: Stores refresh token and session state
   * - ecommerce_mall_admins: Validates current account status
   *
   * Security considerations:
   * - Refresh tokens have longer expiration than access tokens but still expire
   * - Compromised refresh tokens can be invalidated by account status changes
   * - Session metadata enables anomaly detection
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Refresh token for obtaining a new access token
   * @x-autobe-authorization-type refresh
   * @x-autobe-authorization-actor admin
   * @x-autobe-specification Implement token refresh by validating the provided refresh token from the request body. Look up the session in ecommerce_mall_admin_sessions where the refresh token information matches and the session has not expired (expired_at > current time). Verify the associated administrator account status in ecommerce_mall_admins is 'active' - reject refresh for suspended or banned accounts. Generate a new JWT access token with updated expiration time while maintaining the same refresh token or rotating it based on security policy. Update the session record's expiration timestamp if implementing sliding expiration, or create a new session record. Return IEcommerceMallAdmin.IAuthorized with the new access token, the refresh token, and the administrator's profile data including grade and status. Ensure the refresh token itself has appropriate expiration separate from the access token.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("refresh")
  public async refresh(
    @TypedBody()
    body: IEcommerceMallAdmin.IRefresh,
  ): Promise<IEcommerceMallAdmin.IAuthorized> {
    try {
      return await postEcommerceMallAuthAdminRefresh({
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

