@Controller("/ecommerceMall/superAdmin/super-admins/:superAdminId")
export class EcommercemallSuperadminSuper_adminsController {
  /**
   * Retrieve detailed information about a specific super administrator by their unique identifier.
   *
   * This operation returns complete super administrator details including their email address, grade level, creation timestamp, and account status. Super administrators possess the highest privilege level in the platform's administrative hierarchy.
   *
   * The operation requires super administrator authentication. Only super administrators or the subject super administrator can access this information. The response includes the administrator's email, grade, and full audit timestamps.
   *
   * If the specified superAdminId does not exist or is marked as deleted (deleted_at is not null), the operation returns a not found error. The password_hash field is excluded from the response for security reasons.
   *
   * @param connection
   * @param superAdminId Target super administrator's unique identifier (UUID)
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor superAdmin
   * @x-autobe-specification Query the ecommerce_mall_super_admins table by id field (UUID).
   *
   * Implementation steps:
   * 1. Validate authentication - require super admin or admin role
   * 2. Query database: SELECT id, email, grade, created_at, updated_at, deleted_at FROM ecommerce_mall_super_admins WHERE id = :superAdminId
   * 3. If no record found OR deleted_at is not null, throw NOT_FOUND
   * 4. Map result to IEcommerceMallSuperAdmin DTO (exclude password_hash for security)
   * 5. Return the super admin entity
   *
   * Security: Never expose password_hash in response.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get()
  public async at(
    @SuperadminAuth()
    superAdmin: SuperadminPayload,
    @TypedParam("superAdminId")
    superAdminId: string,
  ): Promise<IEcommerceMallSuperAdmin> {
    try {
      return await getEcommerceMallSuperAdminSuperAdminsSuperAdminId({
        superAdmin,
        superAdminId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Demote a super administrator to regular administrator status.
   *
   * This operation allows super administrators to reduce another super administrator's privilege level to regular administrator. The operation is critical for platform governance and administrator hierarchy management.
   *
   * **Self-Demotion Prevention**: The system explicitly prevents super administrators from demoting themselves. This rule ensures that at least one super administrator always remains on the platform to maintain administrative hierarchy integrity. If a super administrator wishes to reduce their own authority level, another super administrator must perform the demotion.
   *
   * **Authorization**: Only super administrators can perform this operation. Regular administrators do not have permission to modify administrator grades.
   *
   * **Validation Rules**:
   * - The target administrator must currently have super administrator grade
   * - The requester cannot be the same as the target (no self-demotion)
   * - After demotion, at least one super administrator must remain in the system
   *
