import { patchEcommerceMallSellerSellerRegistrationsRegistrationIdSnapshots } from "../../../../../providers/patchEcommerceMallSellerSellerRegistrationsRegistrationIdSnapshots";

@Controller(
  "/ecommerceMall/seller/seller-registrations/:registrationId/snapshots",
)
export class EcommercemallSellerSeller_registrationsSnapshotsController {
  /**
   * Retrieve a paginated list of registration snapshots for a specific seller registration.
   *
   * This operation provides administrators and the seller with a complete audit trail of all review events performed on a registration application. Each snapshot captures the review event metadata including which administrator performed the review and the exact timestamp.
   *
   * The snapshots are automatically created by the system when an administrator reviews a seller registration. They serve as immutable historical records for dispute resolution and compliance auditing.
   *
   * Snapshots are read-only and cannot be created, modified, or deleted through this API. The system ensures their integrity and immutability. The response returns a paginated list, allowing browsing through potentially large audit histories.
   *
   * This operation is typically called by administrators reviewing the complete history of a registration, or by sellers wanting to see when and by whom their application was processed.
   *
   * @param connection
   * @param registrationId The unique identifier (UUID) of the seller registration whose snapshots are being queried
   * @param body Search criteria and pagination parameters
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor seller
   * @x-autobe-specification Query the ecommerce_mall_seller_registration_snapshots table filtered by ecommerce_mall_seller_registration_id matching the provided registrationId path parameter.
   *
   * Join with ecommerce_mall_admins via ecommerce_mall_admin_id to retrieve reviewer information (if the snapshot was created during a review by an administrator).
   *
   * Sort results by created_at in descending order (newest snapshots first) by default. Support optional ascending sort.
   *
   * Apply cursor-based pagination using id and created_at as cursor fields for efficient large dataset handling.
   *
   * Authorization: Only accessible to administrators (any level) and the seller who owns the registration. Reject access with 403 Forbidden for other users.
   *
   * Return snapshot data including: id, created_at timestamp, and reviewer information (admin id, name if available).
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async index(
    @SellerAuth()
    seller: SellerPayload,
    @TypedParam("registrationId")
    registrationId: string,
    @TypedBody()
    body: IEcommerceMallSellerRegistrationSnapshot.IRequest,
  ): Promise<IPageIEcommerceMallSellerRegistrationSnapshot.ISummary> {
    try {
      return await patchEcommerceMallSellerSellerRegistrationsRegistrationIdSnapshots(
        {
          seller,
          registrationId,
          body,
        },
      );
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve a specific snapshot from a seller registration's audit trail.
   *
   * This operation fetches a single immutable snapshot record that captures the state of a seller registration review at a specific point in time. Snapshots serve as permanent audit records for compliance and dispute resolution, recording when and by whom the registration was reviewed.
   *
   * Snapshots cannot be modified or deleted once created. They provide a complete historical record of all administrator review actions taken on seller registrations. When a seller is approved or rejected, a snapshot is automatically created capturing the reviewer identity and timestamp.
   *
   * The snapshot retrieved includes metadata such as the administrator who performed the review and the exact timestamp it occurred. The actual registration status and rejection reason at that time were stored in the registration record itself; this snapshot provides the audit trail of who made the decision.
   *
   * This endpoint is accessible to the seller who submitted the registration (to view their own application history) and to administrators (who may view any registration's audit trail for compliance purposes). The seller must be the owner of the registration that the snapshot belongs to; administrators may access snapshots for any registration.
   *
   * @param connection
   * @param registrationId Target registration's ID (global scope)
   * @param snapshotId Target snapshot's ID (global scope)
